from multifactor.IO import IOimport warningswarnings.filterwarnings('ignore')import pandas as pdimport datetimeimport osfrom tqdm import tqdmfrom SIF_Factor_Test10 import SIF_Factor_Test# 调用此函数可得因子库最新符合要求的因子列表def simple_run(libpath, save_result=False, save_path = None, ticker = 'IC.CFE',                corr_threshold = 0.75,               avg_bars_t = 5, ret_per_deal_t = 0.0001,                          long_short_mdd_t = -0.2, IC_t = 0.005,               self_corr_t = 0.75, sharpe_outsample_t = 0.4, sharpe_insample_t = 0.8,               in_start_time = 20170101, in_end_time = 20200101,               out_start_time = 20190101, out_end_time = 20200101):    """    :param libpath: 因子库路径    :param save_result: 是否将筛选出的因子列表保存为csv    :param save_path: 保存路径    :param ticker: 交易品种    :param avg_bars_t: 平均持仓时间阈值    :param rp_per_deal_t: 每笔收益阈值    :param IC_t: IC阈值    :param self_corr_t: 自相关性阈值    :param sharpe_outsample_t: 样本外夏普率阈值    :param sharpe_insample_t: 样本内夏普率阈值    :param in_start_time: 样本内开始时间    :param in_end_time: 样本内结束时间    :param out_start_time: 样本外开始时间    :param out_end_time: 样本外结束时间    :return: 符合要求的因子列表    """    origindata = IO.read_data([in_start_time, in_end_time], columns=['vwap'],                              alt='/data/user/015626/data/share/MD/CHINA_FUTURES/MINUTE/XQUANT_MINUTE/MD_SIF_TICK_TO_MINUTE_RECENT_MONTH.h5')    origindata = origindata.xs(ticker, level=1)    origindata['ret'] = origindata['vwap'].shift(-2) / origindata['vwap'].shift(-1) - 1    origindata = origindata[['ret']]    print('factor test fullhistory')    report_full = get_factor_report(libpath, origindata, ticker=ticker, start_time = in_start_time, end_time = in_end_time)    # report_full.to_csv('/data/user/015626/data/share/factor/factor_test/1min/jiemian_factor_20200930_filter/full_test.csv')    print('factor test outsample')    report_out = get_factor_report(libpath, origindata, ticker=ticker, start_time=out_start_time, end_time=out_end_time)    select_factors = select_factors_from_stats(report_out, report_full, avg_bars_t, ret_per_deal_t,                          long_short_mdd_t, IC_t,                              self_corr_t, sharpe_outsample_t, sharpe_insample_t)    print(len(select_factors))    factor_list = filter_factors(libpath, report_full, ticker=ticker, factorslist=select_factors, corr_threshold=corr_threshold, start_time=in_start_time,                   end_time=in_end_time)    print(len(factor_list))    if save_result:        if not os.path.exists(save_path):            os.makedirs(save_path)        pd.DataFrame({'factor_name':factor_list}).to_csv(os.path.join(save_path, 'latest_factor_' + str(datetime.datetime.now().date()).replace('-','') + '_corr' + str(corr_threshold) + '.csv'), index=False)    return factor_list# 根据因子测试结果筛选因子def select_factors_from_stats(report_out, report_full, avg_bars_t = 5, ret_per_deal_t = 0.0001,                          long_short_mdd_t = -0.2, IC_t = 0.005,                              self_corr_t = 0.75, sharpe_outsample_t = 0.4, sharpe_insample_t = 0.8):    """    :param csvpath1: 样本外因子测试结果（2019年）    :param csvpath2: 样本内因子测试结果（全历史）    :param avg_bars_t: 平均持仓时间阈值    :param rp_per_deal_t: 每笔收益阈值    :param IC_t: IC阈值    :param self_corr_t: 自相关性阈值    :param sharpe_outsample_t: 样本外夏普率阈值    :param sharpe_insample_t: 样本内夏普率阈值    :return: 符合要求的因子列表    """    def select_result_2019(df):        df['avg_bars'] = df[['avg_long_bars','avg_short_bars']].mean(axis =1)        df = df[df.avg_bars >= avg_bars_t]        df = df[df.ret_per_deal >= ret_per_deal_t]        df = df[df['IC-1min'] >= IC_t]        df = df[df['self_corr-shift(5)'] >= self_corr_t]        df = df[df['sharpe_Q3-Q0'] >= sharpe_outsample_t]        df = df[df['long_short_mdd'] >= long_short_mdd_t]        return df.factor_name.tolist()    def select_result_fullhistory(df):        df['avg_bars'] = df[['avg_long_bars','avg_short_bars']].mean(axis =1)        df = df[df.avg_bars >= avg_bars_t]        df = df[df.ret_per_deal >= ret_per_deal_t]        df = df[df['IC-1min'] >= IC_t]        df = df[df['self_corr-shift(5)'] >= self_corr_t]        df = df[df['sharpe_Q3-Q0'] >= sharpe_insample_t]        df = df[df['long_short_mdd'] >= long_short_mdd_t]        return df.factor_name.tolist()    df1namelist = select_result_2019(report_out)    df2namelist = select_result_fullhistory(report_full)    select_factors = list(set(df1namelist) & set(df2namelist))    return select_factors# 从因子库中筛选低相关性因子, 需先使用get_factor_report得到所有因子报告的dataframe，存为csv后传入factor_report_csv_path参数def filter_factors(library_path, report_full, corr_threshold, ticker, factorslist=None,  start_time=20100101,                   end_time=21000101):    """    :param library_path: 因子库路径    :param factor_report_csv_path: 所有因子的测试结果汇总的csv    :param factorslist: 需要特定筛选的因子列表，不传入则对因子库所有因子进行筛选    :param corr_threshold: 筛选的相关性阈值    :param start_time: 读取因子开始时间    :param end_time: 读取因子结束时间    :return: 筛选出的低相关性因子列表    """    if factorslist == None:        alist = os.listdir(library_path)        factorslist = [x[:-3] for x in alist]    print('read all factors')    fullfactors = pd.DataFrame()    for x in factorslist:        # f = IO.read_data([start_time, end_time], alt=os.path.join(library_path, x + '.h5')).xs(ticker, level=1)        f = pd.read_hdf(os.path.join(library_path, x + '.h5'))        # idx = f.index        f = f.loc[str(start_time):str(end_time)]        if len(fullfactors) == 0:            fullfactors = f        else:            fullfactors = fullfactors.join(f)    print('calculate corr between all factors')    corrdf = pd.DataFrame()    count = 0    for i in range(len(factorslist) - 1):        for j in range(i + 1, len(factorslist)):            corrdf.loc[count, 'factor1'] = factorslist[i]            corrdf.loc[count, 'factor2'] = factorslist[j]            corrdf.loc[count, 'corr'] = fullfactors[factorslist[i]].corr(fullfactors[factorslist[j]])            count += 1    corrdf = corrdf.sort_values(by='corr', ascending=False)    # corrdf.to_csv(    #     '/data/user/015626/data/share/factor/factor_test/1min/jiemian_factor_20200929_filter/all_factors_corr.csv',    #     index=False)    print('select high corr factors')    bigcorr = corrdf[corrdf['corr'] > corr_threshold]    if len(bigcorr) == 0:        print('all factors are in low correlation')        return factorslist    bigcorrlist = list(set(bigcorr.factor1.tolist()) | set(bigcorr.factor2.tolist()))    lowcorrlist = list(set(factorslist) - set(bigcorrlist))    # 将相关性高的因子按夏普率从大到小排序    all_factor_report = report_full.copy()    df2bigcorrdf = all_factor_report[all_factor_report.factor_name.isin(bigcorrlist)]    df2bigcorrdf = df2bigcorrdf.sort_values(by='sharpe_Q3-Q0', ascending=False)    waitlist = df2bigcorrdf.factor_name.tolist()    print('start select factors whose correlation is high')    inlist = []    for x in waitlist:        maxcorr = 0        for y in lowcorrlist:            corr = fullfactors[x].corr(fullfactors[y])            maxcorr = max(maxcorr, corr)        if maxcorr <= corr_threshold:            lowcorrlist.append(x)            inlist.append(x)    print('finish!')    return lowcorrlist# 遍历因子库进行因子测试def get_factor_report(rootpath, origindata, ticker, start_time = 20100101, end_time = 20210101, save_path = None, save_image = False):    """    :param rootpath: 因子库路径    :param save_path: 因子测试结果图片保存的路径    :param start_time: 读取因子开始时间    :param end_time: 读取因子结束时间    :param save_image: 是否保存因子结果图片    :return: 所有因子测试结果的汇总dataframe    """    print('startyear', (start_time // 10000))    resultdf = pd.DataFrame()    count = 0    for x in tqdm(os.listdir(rootpath)):        factorname = x[:-3]        # df = IO.read_data([start_time, end_time], alt=os.path.join(rootpath, x)).xs(ticker, level=1)        df = pd.read_hdf(os.path.join(rootpath, x))        # idx = df.index        df = df.loc[str(start_time):str(end_time)]        sif = SIF_Factor_Test(df.join(origindata, how='inner'), factorname, ticker = ticker, save_image=save_image,                              show_image=False, starttime=start_time, endtime=end_time, signal_lims=(-1, 1),                              savepath=save_path)        stats = sif.draw_result()        resultdf.loc[count, 'factor_name'] = factorname        for key in stats.keys():            resultdf.loc[count, key] = stats[key]        count += 1    return resultdflibpath = '/data/user/012398/data/alpha/CHINA_FUTURES/MINUTE/IF_prod/'# libpath = '/data/user/015626/data/share/factor/group/IC_all/'save_path = '/data/user/015626/data/share/factor/factor_test/1min/all_factor_test_20201019/'simple_run(libpath, ticker='IF.CFE', corr_threshold=0.65, save_path=save_path, save_result=True)simple_run(libpath, ticker='IF.CFE', corr_threshold=0.7, save_path=save_path, save_result=True)simple_run(libpath, ticker='IF.CFE', corr_threshold=0.5, save_path=save_path, save_result=True)simple_run(libpath, ticker='IF.CFE', corr_threshold=0.6, save_path=save_path, save_result=True)